class Solution {
public:
    int maxDotProduct(vector<int>& nums1, vector<int>& nums2) {
        if (nums1.size() < nums2.size()) {
            swap(nums1, nums2);
        }
        int n1 = nums1.size();
        int n2 = nums2.size();
        const int NEG_INF = INT_MIN / 2;
        vector<int> dp(n2 + 1, NEG_INF);
        for (int i = n1 - 1; i >= 0; i--) {
            int diag = dp[n2];
            for (int j = n2 - 1; j >= 0; j--) {
                int temp = dp[j];
                int prod = nums1[i] * nums2[j];
                int extend = (diag > 0) ? prod + diag : prod;
                dp[j] = max(extend, max(temp, dp[j + 1]));
                diag = temp;
            }
        }
        return dp[0];
    }
};
